package com.example.tasks.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * Delegated work (data-model.md, Task). The compact constructor mirrors the task-core migration's
 * constraints so an invalid row is never built in memory; services validate user input first and
 * report field errors, so a failure here is a programming error.
 *
 * @param id generated by the database; null until inserted
 * @param deadline null when the task has no deadline
 */
public record Task(
        Long id,
        UUID creatorId,
        UUID assigneeId,
        String title,
        String description,
        Priority priority,
        TaskStatus status,
        Deadline deadline,
        String blockedReason,
        String cancellationReason,
        Instant createdAt,
        Instant updatedAt,
        Instant completedAt,
        long version) {

    public static final int TITLE_MAX = 200;
    public static final int DESCRIPTION_MAX = 20_000;
    public static final int REASON_MAX = 2_000;

    public Task {
        Objects.requireNonNull(creatorId, "creatorId");
        Objects.requireNonNull(assigneeId, "assigneeId");
        Objects.requireNonNull(title, "title");
        Objects.requireNonNull(description, "description");
        Objects.requireNonNull(priority, "priority");
        Objects.requireNonNull(status, "status");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(updatedAt, "updatedAt");
        require(isTrimmedTitle(title), "title must be trimmed and 1..200 characters");
        require(length(description) <= DESCRIPTION_MAX, "description exceeds 20,000 characters");
        require((status == TaskStatus.BLOCKED) == (blockedReason != null), "only blocked has a blocked reason");
        require((status == TaskStatus.CANCELLED) == (cancellationReason != null), "only cancelled has a cancellation reason");
        require((status == TaskStatus.DONE) == (completedAt != null), "only done has a completion time");
        require(blockedReason == null || isReason(blockedReason), "blocked reason must be 1..2,000 characters");
        require(cancellationReason == null || isReason(cancellationReason), "cancellation reason must be 1..2,000 characters");
        require(version > 0, "version must be positive");
    }

    public boolean isParticipant(UUID userId) {
        return creatorId.equals(userId) || assigneeId.equals(userId);
    }

    public boolean isCreator(UUID userId) {
        return creatorId.equals(userId);
    }

    /** A distinct assignee: the assignee of a task they did not create. */
    public boolean isDistinctAssignee(UUID userId) {
        return assigneeId.equals(userId) && !creatorId.equals(userId);
    }

    public Task withId(long newId) {
        return new Task(newId, creatorId, assigneeId, title, description, priority, status, deadline,
                blockedReason, cancellationReason, createdAt, updatedAt, completedAt, version);
    }

    public Task withFields(String newTitle, String newDescription, Priority newPriority) {
        return new Task(id, creatorId, assigneeId, newTitle, newDescription, newPriority, status, deadline,
                blockedReason, cancellationReason, createdAt, updatedAt, completedAt, version);
    }

    public Task withAssignee(UUID newAssignee) {
        return new Task(id, creatorId, newAssignee, title, description, priority, status, deadline,
                blockedReason, cancellationReason, createdAt, updatedAt, completedAt, version);
    }

    public Task withDeadline(Deadline newDeadline) {
        return new Task(id, creatorId, assigneeId, title, description, priority, status, newDeadline,
                blockedReason, cancellationReason, createdAt, updatedAt, completedAt, version);
    }

    public Task withStatus(TaskStatus newStatus, String newBlockedReason, String newCancellationReason, Instant newCompletedAt) {
        return new Task(id, creatorId, assigneeId, title, description, priority, newStatus, deadline,
                newBlockedReason, newCancellationReason, createdAt, updatedAt, newCompletedAt, version);
    }

    /** The next committed version of this task, changed at {@code at}. */
    public Task nextVersion(Instant at) {
        return new Task(id, creatorId, assigneeId, title, description, priority, status, deadline,
                blockedReason, cancellationReason, createdAt, at, completedAt, version + 1);
    }

    static boolean isTrimmedTitle(String value) {
        return !value.isEmpty() && length(value) <= TITLE_MAX && value.strip().equals(value);
    }

    static boolean isReason(String value) {
        return !value.isEmpty() && length(value) <= REASON_MAX;
    }

    /** Length in characters (code points), matching PostgreSQL {@code char_length}. */
    public static int length(String value) {
        return value.codePointCount(0, value.length());
    }

    static void require(boolean condition, String message) {
        if (!condition) {
            throw new IllegalArgumentException(message);
        }
    }
}
